const state = { view: 'overview', dashboard: null, chemicals: [], analysisId: null, analysis: null, graph: null, propertyCatalog: null, propertyX: null, propertyY: null, results: [], liveRecords: {}, libraryFolderId: null, libraryFolders: [], currentChemical: null, pendingLibraryItem: null };
const $ = (s) => document.querySelector(s);
const esc = (v='') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api = async (path, options={}) => { const r = await fetch(path, {headers:{'Content-Type':'application/json'}, ...options}); if(!r.ok) throw new Error((await r.json()).detail || 'Request failed'); const data=await r.json(); if(path==='/api/assistant'){ state.liveRecords=Object.fromEntries((data.results||[]).filter(x=>x.type==='live_chemical').map(x=>[x.id,x])); state.currentAssistantChemical=(data.results||[]).find(x=>x.type==='live_chemical')||null; } return data; };
const toast = (msg) => { const el=$('#toast'); el.textContent=msg; el.classList.add('show'); setTimeout(()=>el.classList.remove('show'),2600); };

// App-wide zoom for the native desktop build and the browser fallback. CSS
// zoom scales the whole workspace together, including the sidebar, dialogs,
// charts, and internal source browser. Keep it separate from chart controls
// and store the preference locally so it survives relaunches.
const APP_ZOOM_STORAGE_KEY = 'chemrd.appZoom.v2';
const APP_ZOOM_DEFAULT = 1.5;
const APP_ZOOM_MIN = 0.5;
const APP_ZOOM_MAX = 2.0;
const APP_ZOOM_STEP = 0.1;
function applyAppZoom(value, announce=false){
  const zoom = Math.min(APP_ZOOM_MAX, Math.max(APP_ZOOM_MIN, Math.round(value * 10) / 10));
  state.appZoom = zoom;
  document.body.style.zoom = `${Math.round(zoom * 100)}%`;
  document.body.dataset.appZoom = String(zoom);
  try { localStorage.setItem(APP_ZOOM_STORAGE_KEY, String(zoom)); } catch (_) { /* storage may be disabled */ }
  if(announce) toast(`App zoom: ${Math.round(zoom * 100)}%`);
}
function initAppZoom(){
  let saved = APP_ZOOM_DEFAULT;
  try { saved = Number(localStorage.getItem(APP_ZOOM_STORAGE_KEY)) || APP_ZOOM_DEFAULT; } catch (_) { /* use the default */ }
  applyAppZoom(saved);
  document.addEventListener('keydown', event => {
    if(!event.ctrlKey || event.altKey || event.metaKey) return;
    if(event.key === '+' || event.key === '='){
      event.preventDefault();
      applyAppZoom((state.appZoom || 1) + APP_ZOOM_STEP, true);
    } else if(event.key === '-' || event.key === '_'){
      event.preventDefault();
      applyAppZoom((state.appZoom || 1) - APP_ZOOM_STEP, true);
    } else if(event.key === '0'){
      event.preventDefault();
      applyAppZoom(APP_ZOOM_DEFAULT, true);
    }
  });
}
const tag = (origin) => `<span class="tag ${origin}">${esc(origin.replaceAll('_',' '))}</span>`;

function shell(title){ $('#crumb').textContent=title; document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===state.view)); }
function header(eyebrow,title,sub,action=''){ return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`; }
function cleanOverviewActivity(){ const heading=document.querySelector('.page-heading h1'); if(heading&&heading.textContent==='Good morning, Anika') heading.textContent='Workspace overview'; const list=document.querySelector('.activity-list'); if(list) list.innerHTML='<div class="empty">No activity yet. Save a chemical, import a source, or create an experiment to begin.</div>'; }
function cleanEmptyGraph(){ if(state.graph&&!state.graph.nodes.length){ const canvas=document.querySelector('.graph-canvas'); if(canvas) canvas.innerHTML='<div class="empty">No linked knowledge yet. Save chemicals, sources, experiments, or reactions to build the graph.</div>'; } }

async function render(){
  const view=$('#view'); view.innerHTML='<div class="empty">Loading workspace…</div>';
  try {
    if(state.view==='overview') { await overview(); cleanOverviewActivity(); }
    if(state.view==='search') searchView();
    if(state.view==='chemicals') await chemicalsView();
    if(state.view==='experiments') await experimentsView();
    if(state.view==='analytics') await analyticsView();
    if(state.view==='graph') { await graphView(); cleanEmptyGraph(); }
    if(state.view==='assistant') assistantView();
    if(state.view==='ingestion') await ingestionView();
  } catch(e) { view.innerHTML=`<div class="panel empty">Could not load this workspace view. ${esc(e.message)}</div>`; }
}

async function overview(){
  shell('Overview'); state.dashboard ||= await api('/api/dashboard'); const d=state.dashboard; const counts=d.counts;
  const origins=d.origin_counts; const total=origins.reduce((a,b)=>a+b.count,0)||1; const colors={measured:'#67e8b4',literature_extracted:'#fbbf70',calculated:'#a9a8ff',model_predicted:'#f6a6d8',ai_estimated:'#53b5ff'};
  $('#view').innerHTML=header('WORKSPACE PULSE','Good morning, Anika','A provenance-aware view of your chemistry and materials R&D program.','<button class="btn primary" onclick="navigate(\'search\')">⌕ Search research</button>')+
    `<div class="stat-grid"><div class="stat-card" style="--glow:rgba(83,181,255,.11);--icon:#53b5ff"><div class="stat-top">Chemical records <span class="stat-icon">⬡</span></div><div class="stat-value">${counts.chemicals}</div><div class="stat-meta"><em>+12%</em> from last review</div></div><div class="stat-card" style="--glow:rgba(103,232,180,.1);--icon:#67e8b4"><div class="stat-top">Active experiments <span class="stat-icon">◌</span></div><div class="stat-value">${counts.experiments}</div><div class="stat-meta"><em>${counts.experiments-1} with recent data</em></div></div><div class="stat-card" style="--glow:rgba(251,191,112,.1);--icon:#fbbf70"><div class="stat-top">Source records <span class="stat-icon">▤</span></div><div class="stat-value">${counts.sources}</div><div class="stat-meta">${counts.sources} license-aware references</div></div><div class="stat-card" style="--glow:rgba(246,166,216,.1);--icon:#f6a6d8"><div class="stat-top">Analytical datasets <span class="stat-icon">⌁</span></div><div class="stat-value">${counts.analyses}</div><div class="stat-meta"><em>5 techniques</em> supported</div></div></div>`+
    `<div class="grid-2"><div class="panel"><div class="panel-head"><div><div class="panel-title">Evidence ledger</div><div class="panel-sub">Every value remains linked to its origin.</div></div><button class="text-link" onclick="navigate('chemicals')">Explore library →</button></div><div class="origin-bar">${origins.map(x=>`<i style="width:${x.count/total*100}%;background:${colors[x.origin]||'#53b5ff'}"></i>`).join('')}</div><div class="origin-legend">${origins.map(x=>`<span style="--c:${colors[x.origin]||'#53b5ff'}">${x.origin.replaceAll('_',' ')} <b>${x.count}</b></span>`).join('')}</div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Recent activity</div><div class="panel-sub">Across your pilot workspace</div></div></div><div class="activity-list"><div class="activity"><i class="activity-dot"></i><div><b>TGA/DTG profile updated</b><small>FR-Resole Pilot 01 · 18 min ago</small></div></div><div class="activity"><i class="activity-dot"></i><div><b>DOPO source linked to reaction</b><small>Patent record · yesterday</small></div></div><div class="activity"><i class="activity-dot"></i><div><b>Compatibility estimate flagged</b><small>Boric acid · needs validation</small></div></div></div></div></div>`+
    `<div class="grid-2"><div class="panel"><div class="panel-head"><div><div class="panel-title">Featured chemical records</div><div class="panel-sub">Identity, properties, and structure at a glance</div></div><button class="text-link" onclick="navigate('chemicals')">View all →</button></div><div class="chem-mini-grid">${d.featured_chemicals.map(c=>`<div class="chem-mini" onclick="showChemical('${c.id}')"><div class="chem-thumb">${c.structure_svg}</div><div><b>${esc(c.name)}</b><small>${esc(c.formula||'formula pending')}</small></div></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Latest source records</div><div class="panel-sub">Traceable references used in this workspace</div></div><button class="text-link" onclick="navigate('ingestion')">Manage →</button></div><div class="source-list">${d.recent_sources.slice(0,3).map(s=>`<div class="source-row"><div class="source-type">${s.source_type==='paper'?'▤':s.source_type==='patent'?'◈':'◌'}</div><div><b>${esc(s.title)}</b><small>${esc(s.publisher||'Internal')}</small></div><time>${s.license.split(' ')[0]}</time></div>`).join('')}</div></div></div>`;
}

function searchView(){ shell('Universal search'); $('#view').innerHTML=header('DISCOVERY','Find across your research','Search the local workspace and, when enabled, live public chemistry and literature sources.')+`<div class="search-hero"><h1>What are you investigating?</h1><p>Try a compound, identifier, DOI, research phrase, or materials question.</p><div class="search-box"><span style="padding:9px 4px 9px 10px;color:#6e859b">⌕</span><input id="search-input" placeholder="Search the research graph or public sources…" onkeydown="if(event.key==='Enter') runSearch()"/><button onclick="runSearch()">Search</button></div><label class="live-toggle"><input id="live-search" type="checkbox" checked/> Search documented public APIs live <span>PubChem · OpenAlex · Crossref · Europe PMC</span></label></div><div id="search-results"></div>`; }
function resultCard(r){ const isLive=r.type?.startsWith('live_'); const type=isLive?r.type.replace('live_','live '):r.type; const body=`<span class="tag">${esc(type)}</span><h3 style="margin:10px 0 0;font-size:13px">${esc(r.name)}</h3><small>${esc(r.subtitle||'')}</small><span style="color:#6e859b;font-size:10px">${esc(r.formula||r.source?.publisher||'')}</span>`; if(r.type==='live_chemical') return `<div class="result-card">${body}<div class="result-actions"><button class="btn ghost" onclick="openSaveChemical('${esc(r.id)}')">＋ Save to library</button>${r.source_url?`<button class="text-link" data-url="${esc(r.source_url)}" data-title="${esc(r.name)}" onclick="openSourcePreview(this.dataset.url,this.dataset.title)">Open source ↗</button>`:''}</div></div>`; if(r.type==='chemical' && !isLive) return `<div class="result-card" onclick="showChemical('${esc(r.id)}')">${body}<div class="result-actions"><button class="btn ghost" onclick="event.stopPropagation();openSaveLocalChemical('${esc(r.id)}','${esc(r.name)}')">＋ Save to folder</button></div></div>`; if(r.source_url) return `<div class="result-card" data-url="${esc(r.source_url)}" data-title="${esc(r.name)}" onclick="openSourcePreview(this.dataset.url,this.dataset.title)">${body}<small style="color:#53b5ff">Open in internal browser ↗</small></div>`; return `<div class="result-card" onclick="toast('This record is available in the workspace graph')">${body}</div>`; }
function openSourcePreview(url,title){ if(window.pywebview?.api?.open_source){ window.pywebview.api.open_source(url,title||'Source').catch(()=>toast('The native source window could not be opened')); return; } let reader=document.getElementById('internal-browser'); if(!reader){ document.body.insertAdjacentHTML('beforeend',`<div id="internal-browser" class="internal-browser" role="dialog" aria-modal="true" aria-label="Internal source browser"><div class="internal-browser-shell"><div class="internal-browser-toolbar"><button class="icon-button" onclick="closeSourcePreview()" aria-label="Close browser">×</button><div class="reader-title" id="reader-title">Source preview</div><div class="reader-address" id="reader-address"></div><a class="btn ghost reader-external" id="reader-external" target="_blank" rel="noreferrer">External ↗</a></div><div class="reader-status" id="reader-status">Loading source…</div><iframe id="reader-frame" title="Internal source browser" sandbox="allow-forms allow-modals allow-popups allow-presentation allow-same-origin allow-scripts"></iframe><div class="reader-footer">Some publishers block embedded previews. If a publisher blocks iframe embedding, use the native ChemR&D desktop build for a full internal source window.</div></div></div>`); reader=document.getElementById('internal-browser'); } $('#reader-title').textContent=title||'Source preview'; $('#reader-address').textContent=url; $('#reader-external').href=url; $('#reader-status').textContent='Loading source…'; $('#reader-frame').onload=()=>$('#reader-status').textContent='Source loaded · review the original page and its license'; $('#reader-frame').src=url; reader.classList.add('open'); document.body.classList.add('reader-open'); }
function closeSourcePreview(){ const reader=document.getElementById('internal-browser'); if(!reader) return; reader.classList.remove('open'); document.body.classList.remove('reader-open'); const frame=document.getElementById('reader-frame'); if(frame) frame.src='about:blank'; }
async function runSearch(){ const q=$('#search-input').value.trim(); if(!q) return; const live=$('#live-search')?.checked ?? true; const data=await api('/api/search?q='+encodeURIComponent(q)+'&live='+live); state.results=data.results; state.liveRecords=Object.fromEntries(data.results.filter(r=>r.type==='live_chemical').map(r=>[r.id,r])); const liveCount=data.live?.results?.length||0; $('#search-results').innerHTML=`<div class="panel-head"><div><div class="panel-title">${data.results.length} results for “${esc(q)}”</div><div class="panel-sub">${live?`Live retrieval returned ${liveCount} public-source matches.`:'Local workspace records only.'}</div></div></div>${data.results.length?`<div class="result-grid">${data.results.map(resultCard).join('')}</div>`:'<div class="panel empty">No matching records. Try a broader term or enable live public-source search.</div>'}`; }

function libraryItemTypeLabel(item){ return item.item_type==='chemical'?'chemical record':item.item_type; }
function libraryItemsHtml(items){ if(!items.length) return '<div class="empty">Nothing saved in this folder yet.</div>'; return items.map(item=>`<div class="library-item"><div><span class="tag">${esc(libraryItemTypeLabel(item))}</span><b>${esc(item.title)}</b><small>${esc(item.chemical_name||item.source_title||item.content||'')}</small></div><div>${item.url?`<button class="text-link" data-url="${esc(item.url)}" data-title="${esc(item.title)}" onclick="openSourcePreview(this.dataset.url,this.dataset.title)">Open ↗</button>`:''}</div></div>`).join(''); }
async function selectLibraryFolder(id){ state.libraryFolderId=id; await chemicalsView(); }
async function openNewLibraryFolder(){ const name=window.prompt('Folder name'); if(!name?.trim()) return; const description=window.prompt('What is this folder for?')||''; try { await api('/api/library/folders',{method:'POST',body:JSON.stringify({name,description})}); toast('Folder created'); await chemicalsView(); } catch(e){ toast(e.message); } }
function openSaveChemical(id){ const record=state.liveRecords[id]; if(!record){ toast('Search result is no longer available; run the search again'); return; } openFolderPicker({kind:'live_chemical',record}).catch(e=>toast(e.message)); }
function openSaveLocalChemical(id,title){ openFolderPicker({kind:'local_chemical',chemical_id:id,title}).catch(e=>toast(e.message)); }
function openNewLibraryItem(){ openFolderPicker({kind:'generic'}).catch(e=>toast(e.message)); }
async function openFolderPicker(pending){ state.pendingLibraryItem=pending; const folders=await api('/api/library/folders'); const fields=pending.kind==='generic'?`<label class="library-field">Type<select id="library-item-type"><option value="website">Website</option><option value="paper">Paper</option><option value="patent">Patent</option><option value="note">Note</option><option value="experiment">Experiment</option><option value="file">File</option><option value="other">Other</option></select></label><label class="library-field">Title<input id="library-item-title" placeholder="What are you saving?"/></label><label class="library-field">URL<input id="library-item-url" placeholder="https://…"/></label><label class="library-field">Notes<textarea id="library-item-content" placeholder="Optional notes"></textarea></label>`:''; document.getElementById('library-modal')?.remove(); document.body.insertAdjacentHTML('beforeend',`<div id="library-modal" class="library-modal"><div class="library-modal-card"><div class="panel-head"><div><div class="panel-title">${pending.kind==='generic'?'Add to chemical library':'Save to chemical library'}</div><div class="panel-sub">Choose a folder. You can move or reuse this item later.</div></div><button class="icon-button" onclick="closeLibraryModal()">×</button></div><label class="library-field">Folder<select id="library-folder-select">${folders.map(f=>`<option value="${esc(f.id)}">${esc(f.name)} · ${f.item_count} items</option>`).join('')}</select></label>${fields}<div class="library-modal-actions"><button class="btn ghost" onclick="openNewLibraryFolderFromPicker()">＋ New folder</button><span></span><button class="btn ghost" onclick="closeLibraryModal()">Cancel</button><button class="btn primary" onclick="confirmFolderSave()">Save</button></div></div></div>`); }
async function openNewLibraryFolderFromPicker(){ const name=window.prompt('Folder name'); if(!name?.trim()) return; const description=window.prompt('What is this folder for?')||''; try { await api('/api/library/folders',{method:'POST',body:JSON.stringify({name,description})}); const pending=state.pendingLibraryItem; await openFolderPicker(pending); } catch(e){ toast(e.message); } }
function closeLibraryModal(){ document.getElementById('library-modal')?.remove(); state.pendingLibraryItem=null; }
async function confirmFolderSave(){ const pending=state.pendingLibraryItem; const folder_id=$('#library-folder-select')?.value; if(!pending||!folder_id) return; try { let result; if(pending.kind==='live_chemical') result=await api('/api/library/chemicals',{method:'POST',body:JSON.stringify({folder_id,record:pending.record})}); else if(pending.kind==='local_chemical') result=await api('/api/library/items',{method:'POST',body:JSON.stringify({folder_id,item_type:'chemical',title:pending.title,chemical_id:pending.chemical_id})}); else result=await api('/api/library/items',{method:'POST',body:JSON.stringify({folder_id,item_type:$('#library-item-type').value,title:$('#library-item-title').value,url:$('#library-item-url').value,content:$('#library-item-content').value})}); closeLibraryModal(); toast(`Saved to ${result.folder_name||'chemical library'}`); if(state.view==='chemicals') await chemicalsView(); } catch(e){ toast(e.message); } }
async function chemicalsView(){ shell('Chemical library'); const data=state.chemicals.length?state.chemicals:(state.chemicals=await api('/api/chemicals')); const folders=await api('/api/library/folders'); state.libraryFolders=folders; if(!state.libraryFolderId||!folders.some(f=>f.id===state.libraryFolderId)) state.libraryFolderId=folders[0]?.id||null; const items=state.libraryFolderId?await api('/api/library/folders/'+encodeURIComponent(state.libraryFolderId)+'/items'):[]; const selected=folders.find(f=>f.id===state.libraryFolderId); const folderCards=folders.map(f=>`<button class="library-folder ${f.id===state.libraryFolderId?'active':''}" onclick="selectLibraryFolder('${esc(f.id)}')"><b>${esc(f.name)}</b><small>${f.item_count} saved items</small></button>`).join(''); $('#view').innerHTML=header('CHEMISTRY GRAPH','Chemical library','Canonical chemical records plus folders for papers, websites, notes, patents, experiments, and other research material.',`<div class="header-actions"><button class="btn ghost" onclick="openNewLibraryFolder()">＋ New folder</button><button class="btn primary" onclick="openNewLibraryItem()">＋ Add research item</button></div>`)+`<div class="library-folder-strip">${folderCards}</div><div class="panel library-items-panel"><div class="panel-head"><div><div class="panel-title">${esc(selected?.name||'Library items')}</div><div class="panel-sub">${esc(selected?.description||'Choose a folder to see saved research.')}</div></div></div>${libraryItemsHtml(items)}</div><div class="panel"><div class="panel-head"><div><div class="panel-title">${data.length} canonical chemical records</div><div class="panel-sub">Select a record to inspect structure and provenance.</div></div><input class="select" placeholder="Filter records…" oninput="filterTable(this.value)" style="width:190px"/></div><div class="table-wrap"><table class="data-table" id="chem-table"><thead><tr><th>Record</th><th>Formula</th><th>CAS / ID</th><th>Structure</th><th>Save</th></tr></thead><tbody>${data.map(c=>`<tr onclick="showChemical('${c.id}')" style="cursor:pointer"><td><b>${esc(c.name)}</b><br><span style="font-size:10px;color:#71879b">${esc(c.synonyms?.[0]||'')}</span></td><td>${esc(c.formula||'—')}</td><td>${esc(c.cas_number||c.id)}</td><td><div class="chem-thumb">${c.structure_svg}</div></td><td><button class="btn ghost" onclick="event.stopPropagation();openSaveLocalChemical('${esc(c.id)}','${esc(c.name)}')">＋ Save</button></td></tr>`).join('')}</tbody></table></div></div>`; }
function filterTable(q){ document.querySelectorAll('#chem-table tbody tr').forEach(row=>row.style.display=row.textContent.toLowerCase().includes(q.toLowerCase())?'':'none'); }
function ensureChemicalSaveButton(){ const head=document.querySelector('.structure-layout .panel .panel-head'); const c=state.currentChemical; if(!head||!c||head.querySelector('.chemical-save-button')) return; head.insertAdjacentHTML('beforeend',`<button class="btn ghost chemical-save-button" onclick="openSaveLocalChemical('${esc(c.id)}','${esc(c.name)}')">＋ Save to folder</button>`); }
function setupMolViewer(smiles,id){ ensureChemicalSaveButton(); const host=document.getElementById('mol3d-'+id); if(!host || !window.$3Dmol || !smiles) return; host.innerHTML=''; const viewer=window.$3Dmol.createViewer(host,{backgroundColor:'#071421'}); viewer.addModel(smiles,'smi'); viewer.setStyle({}, {stick:{radius:0.13}, sphere:{scale:0.24}}); viewer.zoomTo(); viewer.spin('y',0.45); viewer.render(); host.dataset.ready='true'; }
async function showChemical(id){ const c=await api('/api/chemicals/'+id); $('#view').innerHTML=header('CHEMICAL RECORD',c.name, c.description || 'Identity, structure, and evidence ledger.')+`<div class="structure-layout"><div><div class="panel"><div class="panel-head"><div><div class="panel-title">2D structure</div><div class="panel-sub">RDKit rendering when available; safe fallback otherwise.</div></div><span class="tag">${esc(c.id)}</span></div><div class="structure-art">${c.structure_svg}</div><div class="detail-meta"><div class="meta-box"><small>Formula</small><b>${esc(c.formula||'—')}</b></div><div class="meta-box"><small>Molecular weight</small><b>${c.molecular_weight?c.molecular_weight+' g/mol':'—'}</b></div><div class="meta-box"><small>CAS</small><b>${esc(c.cas_number||'Not assigned')}</b></div><div class="meta-box"><small>InChIKey</small><b>${esc(c.inchikey||'Not assigned')}</b></div></div><div class="origin-note"><span>✓</span>Structure and identity are record-level facts; downstream properties carry their own origin.</div></div></div><div><div class="panel" style="margin-bottom:17px"><div class="panel-head"><div><div class="panel-title">Interactive 3D preview</div><div class="panel-sub">3Dmol.js viewer with a dependency-free offline fallback.</div></div><button class="text-link" onclick="toast('Drag to rotate · scroll to zoom when 3Dmol.js is available')">Viewer help</button></div><div class="viewer-3d" id="mol3d-${esc(c.id)}"><span class="bond b1"></span><span class="bond b2"></span><span class="bond b3"></span><span class="bond b4"></span><span class="atom">C</span><span class="atom">O</span><span class="atom">C</span><span class="atom">H</span><span class="atom">O</span><span class="viewer-label">3D molecular stage · ${esc(c.formula||'')}</span></div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Property ledger</div><div class="panel-sub">No silent mixing of evidence types.</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Property</th><th>Value</th><th>Origin</th><th>Source</th></tr></thead><tbody>${c.properties.map(p=>`<tr><td><b>${esc(p.property_name.replaceAll('_',' '))}</b><br><small style="color:#6f8599">${esc(p.method||'method not specified')}</small></td><td>${esc(p.value_text)} ${esc(p.unit||'')}</td><td>${tag(p.origin)}</td><td><small>${esc(p.source_title||'No source link')}</small></td></tr>`).join('')}</tbody></table></div></div></div></div>`; setTimeout(()=>setupMolViewer(c.smiles,c.id),0); }

function chemicalPropertiesTable(c){ const props=(c.properties||[]); if(!props.length) return '<div class="empty">No source-linked properties have been saved for this record yet.</div>'; return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Property</th><th>Value</th><th>Origin</th><th>Source</th></tr></thead><tbody>${props.map(p=>`<tr><td><b>${esc(p.property_name.replaceAll('_',' '))}</b><br><small style="color:#6f8599">${esc(p.method||'method not specified')}</small></td><td>${esc(p.value_text)} ${esc(p.unit||'')}</td><td>${tag(p.origin)}</td><td><small>${esc(p.source_title||'No source link')}</small></td></tr>`).join('')}</tbody></table></div>`; }
function moleculeStyleObject(style){ if(style==='sphere') return {sphere:{scale:0.34,colorscheme:'Jmol'}}; if(style==='stick') return {stick:{radius:0.16,colorscheme:'Jmol'}}; return {stick:{radius:0.16,colorscheme:'Jmol'},sphere:{scale:0.24,colorscheme:'Jmol'}}; }
function setMoleculeStyle(style){ const item=state.moleculeViewer; if(!item?.viewer)return; item.style=style; item.viewer.setStyle({},moleculeStyleObject(style)); item.viewer.render(); }
function resetMoleculeView(){ const item=state.moleculeViewer; if(!item?.viewer)return; item.viewer.zoomTo(); item.viewer.render(); }
function toggleMoleculeSpin(){ const item=state.moleculeViewer; if(!item?.viewer)return; item.spinning=!item.spinning; item.viewer.spin(item.spinning?'y':false,0.18); const button=$('#molecule-spin'); if(button) button.textContent=item.spinning?'Stop spin':'Spin'; }
function setupMolViewerClean(smiles,id,conformerUrl){ const host=document.getElementById('mol3d-'+id); if(!host)return; const fallback=host.querySelector('.viewer-fallback'),loading=host.querySelector('.viewer-loading'); const showFallback=()=>{ if(loading) loading.hidden=true; if(fallback) fallback.hidden=false; }; if(!window.$3Dmol){ showFallback(); return; } const viewer=window.$3Dmol.createViewer(host,{backgroundColor:'#071421',antialias:true}); state.moleculeViewer={viewer,style:'ball',spinning:false}; const renderModel=()=>{ viewer.setStyle({},moleculeStyleObject('ball')); viewer.zoomTo(); viewer.render(); if(loading) loading.hidden=true; }; const loadSmiles=()=>{ try{ viewer.addModel(smiles,'smi'); renderModel(); }catch(_){ showFallback(); } }; if(conformerUrl){ fetch(conformerUrl).then(r=>{if(!r.ok)throw new Error('3D conformer unavailable');return r.text()}).then(sdf=>{ try{ viewer.addModel(sdf,'sdf'); renderModel(); }catch(_){ loadSmiles(); } }).catch(()=>loadSmiles()); } else loadSmiles(); }
async function showChemicalClean(id){ const c=await api('/api/chemicals/'+id); state.currentChemical=c; const iupac=c.properties?.find(p=>p.property_name==='iupac_name')?.value_text || c.description || ''; const image=c.structure_2d_url?`<img class="structure-image" src="${esc(c.structure_2d_url)}" alt="2D structure of ${esc(c.name)}" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><div class="structure-fallback" hidden><b>2D depiction unavailable</b><small>Use the canonical SMILES below or retry when the public structure service is available.</small></div>`:`<div class="structure-fallback"><b>2D depiction unavailable</b><small>Use the canonical SMILES below.</small></div>`; $('#view').innerHTML=header('CHEMICAL RECORD',c.name,'Identity, structure, and source-linked evidence.')+`<div class="chemical-overview"><div><span class="tag">${esc(c.id)}</span><p class="chemical-iupac"><b>IUPAC name</b>${esc(iupac||'Not available')}</p></div><button class="btn ghost" onclick="openSaveLocalChemical('${esc(c.id)}','${esc(c.name)}')">＋ Save to folder</button></div><div class="structure-layout"><div><div class="panel"><div class="panel-head"><div><div class="panel-title">2D structure</div><div class="panel-sub">Canonical PubChem depiction, with an honest availability state if the source is unreachable.</div></div></div><div class="structure-art enhanced-structure-art">${image}</div><div class="structure-code"><small>Canonical SMILES</small><code>${esc(c.smiles||'Not available')}</code></div><div class="detail-meta"><div class="meta-box"><small>Formula</small><b>${esc(c.formula||'—')}</b></div><div class="meta-box"><small>Molecular weight</small><b>${c.molecular_weight?c.molecular_weight+' g/mol':'—'}</b></div><div class="meta-box"><small>CAS</small><b>${esc(c.cas_number||'Not assigned')}</b></div><div class="meta-box"><small>InChIKey</small><b>${esc(c.inchikey||'Not assigned')}</b></div></div><div class="origin-note"><span>✓</span>Identity and structure are kept separate from measured or calculated properties.</div></div></div><div><div class="panel" style="margin-bottom:17px"><div class="panel-head"><div><div class="panel-title">Interactive 3D conformer</div><div class="panel-sub">PubChem 3D SDF when available; SMILES is used only as a fallback.</div></div><div class="viewer-tools"><select class="select" aria-label="3D representation" onchange="setMoleculeStyle(this.value)"><option value="ball" selected>Ball &amp; stick</option><option value="stick">Sticks</option><option value="sphere">Space fill</option></select><button class="btn ghost" onclick="resetMoleculeView()">Reset</button><button class="btn ghost" id="molecule-spin" onclick="toggleMoleculeSpin()">Spin</button><a class="text-link" href="${esc(c.conformer_3d_url||'#')}" download>Download SDF</a></div></div><div class="viewer-3d enhanced-viewer" id="mol3d-${esc(c.id)}"><div class="viewer-loading">Loading 3D conformer…</div><div class="viewer-fallback" hidden><b>3D conformer unavailable</b><small>The 2D structure and canonical SMILES remain available. Check the source connection and try again.</small></div></div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Property ledger</div><div class="panel-sub">Every value retains its origin and source.</div></div></div>${chemicalPropertiesTable(c)}</div></div></div>`; setTimeout(()=>setupMolViewerClean(c.smiles,c.id,c.conformer_3d_url),0); }
async function experimentsView(){ shell('Experiments'); const [experiments, forms, reactions]=await Promise.all([api('/api/experiments'),api('/api/formulations'),api('/api/reactions')]); $('#view').innerHTML=header('R&D OPERATIONS','Experiments & process records','Keep objectives, formulations, reaction conditions, and analytical follow-up connected.','<button class="btn primary" onclick="openNewExperimentWizard()">＋ New experiment</button>')+`<div class="grid-2"><div class="panel"><div class="panel-head"><div><div class="panel-title">Experiment register</div><div class="panel-sub">${experiments.length} records in the pilot workspace.</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Experiment</th><th>Status</th><th>Owner</th><th>Materials</th></tr></thead><tbody>${experiments.map(e=>`<tr><td><b>${esc(e.name)}</b><br><small style="color:#71869b">${esc(e.objective)}</small></td><td><span class="status ${e.status}">${esc(e.status.replace('_',' '))}</span></td><td>${esc(e.owner)}</td><td>${e.chemical_ids.length} linked</td></tr>`).join('')}</tbody></table></div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Formulations</div><div class="panel-sub">Composition is versionable and source-linked.</div></div></div>${forms.map(f=>`<div class="source-row"><div class="source-type">⚗</div><div><b>${esc(f.name)}</b><small>${esc(f.purpose)}</small></div><span class="status">${esc(f.status)}</span></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Reaction & process records</div><div class="panel-sub">Inputs, outputs, conditions, and yield are separate from property evidence.</div></div></div><div class="result-grid">${reactions.map(r=>`<div class="result-card"><span class="tag">${esc(r.reaction_type)}</span><h3 style="margin:10px 0 4px;font-size:13px">${esc(r.name)}</h3><small>${Object.entries(r.conditions).map(([k,v])=>`${esc(k)}: ${esc(v)}`).join(' · ')}</small><div style="color:#70dcb9;font-size:11px;margin-top:10px">${esc(r.yield_text||'yield not recorded')}</div></div>`).join('')}</div></div>`; }

function propertyChartSvg(catalog,xKey,yKey){ const xm=catalog.metrics.find(m=>m.key===xKey),ym=catalog.metrics.find(m=>m.key===yKey); if(!xm||!ym) return '<div class="empty">Choose an X and Y metric to draw the comparison.</div>'; const points=catalog.points.map(p=>{const x=p.values?.[xKey],y=p.values?.[yKey]; return x&&y&&Number.isFinite(Number(x.value))&&Number.isFinite(Number(y.value))?{name:p.name,x:Number(x.value),y:Number(y.value),xs:x,ys:y}:null}).filter(Boolean); if(!points.length) return `<div class="empty">No chemicals currently have both “${esc(xm.label)}” and “${esc(ym.label)}”. Add numeric property evidence with matching metrics to plot them.</div>`; const W=820,H=360,pad={l:64,r:24,t:24,b:54},xs=points.map(p=>p.x),ys=points.map(p=>p.y),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),xpad=(xmax-xmin||1)*.12,ypad=(ymax-ymin||1)*.12,x0=xmin-xpad,x1=xmax+xpad,y0=ymin-ypad,y1=ymax+ypad,X=v=>pad.l+(v-x0)/(x1-x0||1)*(W-pad.l-pad.r),Y=v=>H-pad.b-(v-y0)/(y1-y0||1)*(H-pad.t-pad.b); return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(ym.label)} versus ${esc(xm.label)}"><g stroke="#1b3449" stroke-width="1">${[0,1,2,3,4].map(i=>`<line x1="${pad.l}" x2="${W-pad.r}" y1="${pad.t+i*(H-pad.t-pad.b)/4}" y2="${pad.t+i*(H-pad.t-pad.b)/4}"/>`).join('')}</g><g fill="#9ab0c2" font-size="10"><text x="${pad.l}" y="${H-12}">${x0.toFixed(2)}</text><text x="${W-pad.r-36}" y="${H-12}">${x1.toFixed(2)}</text><text x="8" y="${H-pad.b}">${y0.toFixed(2)}</text><text x="8" y="${pad.t+5}">${y1.toFixed(2)}</text><text x="${W/2}" y="${H-2}" text-anchor="middle">${esc(xm.label)}${xm.unit?' · '+esc(xm.unit):''}</text><text x="14" y="${H/2}" text-anchor="middle" transform="rotate(-90 14 ${H/2})">${esc(ym.label)}${ym.unit?' · '+esc(ym.unit):''}</text></g>${points.map(pt=>`<circle cx="${X(pt.x).toFixed(1)}" cy="${Y(pt.y).toFixed(1)}" r="6" fill="#53b5ff" stroke="#dbeafe" stroke-width="1.5"><title>${esc(pt.name)} · X ${pt.x} ${esc(pt.xs.unit||'')} · Y ${pt.y} ${esc(pt.ys.unit||'')} · ${esc(pt.ys.origin)}</title></circle>`).join('')}</svg>`; }
function renderPropertyComparison(catalog){ state.propertyCatalog=catalog; const metrics=catalog.metrics||[]; if(metrics.length<2) return '<div class="panel empty">No two numeric chemical metrics are available yet. Add chemical property evidence to enable X-versus-Y plots.</div>'; const xKey=state.propertyX&&metrics.some(m=>m.key===state.propertyX)?state.propertyX:metrics[0].key, yKey=state.propertyY&&metrics.some(m=>m.key===state.propertyY)?state.propertyY:(metrics.find(m=>m.key!==xKey)?.key||metrics[0].key); state.propertyX=xKey; state.propertyY=yKey; const options=(selected)=>metrics.map(m=>`<option value="${esc(m.key)}" ${m.key===selected?'selected':''}>${esc(m.label)}${m.unit?' · '+esc(m.unit):''}</option>`).join(''); return `<div class="panel property-comparison-panel"><div class="panel-head"><div><div class="panel-title">Chemical property comparison</div><div class="panel-sub">Choose any two numeric metrics. Origins stay explicit in each selector and point tooltip.</div></div><div class="chart-controls"><label class="library-field">X axis<select class="select" id="property-x-select" onchange="updatePropertyPlot()">${options(xKey)}</select></label><label class="library-field">Y axis<select class="select" id="property-y-select" onchange="updatePropertyPlot()">${options(yKey)}</select></label></div></div><div class="chart-box" id="property-chart">${propertyChartSvg(catalog,xKey,yKey)}</div><div class="origin-note"><span>i</span>Only chemicals with both selected values appear. Measured, literature-extracted, calculated, predicted, and AI-estimated values are never combined under one metric.</div></div>`; }
function updatePropertyPlot(){ const x=$('#property-x-select')?.value,y=$('#property-y-select')?.value; if(!state.propertyCatalog||!x||!y)return; state.propertyX=x; state.propertyY=y; const chart=$('#property-chart'); if(chart) chart.innerHTML=propertyChartSvg(state.propertyCatalog,x,y); }
async function analyticsView(){ shell('Analysis workspace'); const [catalog,analyses]=await Promise.all([api('/api/plots/chemical-properties'),api('/api/analyses')]); const comparison=renderPropertyComparison(catalog); if(!analyses.length){ $('#view').innerHTML=header('EVIDENCE WORKSPACE','Analysis workspace','Choose chemical metrics for X-versus-Y comparisons, or connect a TGA/DTG, DSC, FTIR, NMR, XRD, or generic dataset.')+comparison+'<div class="panel empty">No analytical datasets yet. Add an experiment or import a licensed/local measurement to create the first signal plot.</div>'; return; } if(!state.analysisId||!analyses.some(x=>x.id===state.analysisId)) state.analysisId=analyses[0].id; state.analysis=await api('/api/analyses/'+state.analysisId); const a=state.analysis; $('#view').innerHTML=header('EVIDENCE WORKSPACE','Analysis workspace','Choose chemical properties or explore uploaded analytical signals with comparison overlays.')+comparison+`<div class="chart-layout"><div class="panel"><div class="panel-head"><div><div class="panel-title">${esc(a.title)}</div><div class="panel-sub">${esc(a.technique)} · ${esc(a.x_unit)} vs ${esc(a.y_unit)} · ${tag(a.origin)}</div></div><div class="chart-controls"><select class="select" onchange="loadAnalysis(this.value)">${analyses.map(x=>`<option value="${x.id}" ${x.id===a.id?'selected':''}>${esc(x.technique)} · ${esc(x.title)}</option>`).join('')}</select><button class="btn ghost" onclick="toast('Overlay controls are ready for additional series')">＋ Overlay</button></div></div><div class="chart-box">${chartSvg(a.series)}</div><div class="chart-legend">${a.series.map((s,i)=>`<span><i style="--c:${i?'#fbbf70':'#53b5ff'}"></i>${esc(s.name)} · ${esc(s.origin)}</span>`).join('')}</div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Techniques</div><div class="panel-sub">A single workspace, many signals.</div></div></div><div class="technique-list">${['TGA/DTG','DSC','FTIR','NMR','XRD','Generic'].map(t=>`<button class="technique ${a.technique===t?'active':''}" onclick="selectTechnique('${t}')"><b>${t}</b><small>${t==='TGA/DTG'?'mass + derivative':t==='DSC'?'heat flow':'spectrum / trace'}</small></button>`).join('')}</div><div class="origin-note" style="margin-top:18px"><span>i</span>Overlay lines are labeled by origin and source. Comparison does not imply equivalence.</div></div></div>`; }
function chartSvg(series){ const all=series.flatMap(s=>s.points), xs=all.map(p=>p[0]), ys=all.map(p=>p[1]), xmin=Math.min(...xs), xmax=Math.max(...xs), ymin=Math.min(...ys), ymax=Math.max(...ys); const W=800,H=300,p={l:45,r:18,t:15,b:35}; const X=x=>p.l+(x-xmin)/(xmax-xmin||1)*(W-p.l-p.r),Y=y=>H-p.b-(y-ymin)/(ymax-ymin||1)*(H-p.t-p.b); const colors=['#53b5ff','#fbbf70','#67e8b4']; const paths=series.map((s,i)=>`<path d="${s.points.map((pt,j)=>(j?'L':'M')+X(pt[0]).toFixed(1)+' '+Y(pt[1]).toFixed(1)).join(' ')}" fill="none" stroke="${colors[i%colors.length]}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`).join(''); return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><g stroke="#1b3449" stroke-width="1">${[0,1,2,3,4].map(i=>`<line x1="${p.l}" x2="${W-p.r}" y1="${p.t+i*(H-p.t-p.b)/4}" y2="${p.t+i*(H-p.t-p.b)/4}"/>`).join('')}</g><g fill="#6f879c" font-size="10"><text x="${p.l}" y="${H-8}">${xmin}</text><text x="${W-p.r-25}" y="${H-8}">${xmax}</text><text x="5" y="${H-p.b}">${ymin.toFixed(1)}</text><text x="5" y="${p.t+5}">${ymax.toFixed(1)}</text></g>${paths}</svg>`; }
async function loadAnalysis(id){ state.analysisId=id; state.analysis=await api('/api/analyses/'+id); await analyticsView(); }
async function selectTechnique(t){ const analyses=await api('/api/analyses'); const found=analyses.find(a=>a.technique===t); if(found) await loadAnalysis(found.id); else toast(`${t} demo series is ready for connector import`); }

async function graphView(){ shell('Knowledge graph'); state.graph ||= await api('/api/graph'); const g=state.graph; const positions={}; const W=900,H=500; g.nodes.forEach((n,i)=>{ const ring=n.type==='chemical'?170:240; const centerX=450,centerY=250; const chemIndex=g.nodes.filter(x=>x.type===n.type).indexOf(n); const total=g.nodes.filter(x=>x.type===n.type).length; positions[n.id]={x:centerX+ring*Math.cos(chemIndex/Math.max(total,1)*Math.PI*2-1.5),y:centerY+ring*.72*Math.sin(chemIndex/Math.max(total,1)*Math.PI*2-1.5)}; }); const edges=g.edges.map(e=>{const s=positions[e.source],t=positions[e.target]; return s&&t?`<line x1="${s.x}" y1="${s.y}" x2="${t.x}" y2="${t.y}" stroke="#37617c" stroke-width="1.4" stroke-dasharray="4 4"/>`:''}).join(''); const nodes=g.nodes.map(n=>{const p=positions[n.id],color=n.type==='chemical'?'#53b5ff':n.type==='experiment'?'#67e8b4':'#fbbf70'; return `<g><circle cx="${p.x}" cy="${p.y}" r="${n.type==='chemical'?11:9}" fill="${color}" fill-opacity=".9"/><text x="${p.x}" y="${p.y+25}" text-anchor="middle" fill="#a5b8c9" font-size="10">${esc(n.label).slice(0,23)}</text></g>`}).join(''); $('#view').innerHTML=header('CONNECTED KNOWLEDGE','Knowledge graph','See how chemicals, experiments, reactions, and evidence records reinforce or qualify each other.')+`<div class="panel"><div class="panel-head"><div><div class="panel-title">Workspace graph</div><div class="panel-sub">${g.nodes.length} nodes · ${g.edges.length} relationships · click a chemical in the library for full provenance.</div></div><button class="btn ghost" onclick="toast('Graph filters can be added through the same API')">Filter graph</button></div><div class="graph-canvas"><svg viewBox="0 0 ${W} ${H}">${edges}${nodes}</svg><div class="graph-legend"><span style="--c:#53b5ff">chemical</span><span style="--c:#67e8b4">experiment</span><span style="--c:#fbbf70">reaction</span></div></div></div>`; }

function assistantView(){ shell('Research assistant'); $('#view').innerHTML=header('CITATION-FIRST AI','Research assistant','Ask chemistry, materials, or general scientific questions. Relevant citations are shown when retrieval finds them; otherwise the answer is clearly labeled as general AI knowledge.')+`<div class="assistant-layout"><div class="panel chat-window"><div class="chat-messages" id="chat-messages"><div class="message"><div class="avatar">✦</div><div><div class="bubble">I can answer general scientific questions, identify compounds, and synthesize relevant public research. Unrelated search hits are filtered out instead of being presented as evidence.</div><small>Assistant · OpenAI → Gemini → Groq fallback ready</small></div></div></div><div class="chat-input"><input id="assistant-input" placeholder="e.g. How does pH affect chemical stability?" onkeydown="if(event.key==='Enter')askAssistant()"/><button class="btn primary" onclick="askAssistant()">Ask</button></div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Retrieval controls</div><div class="panel-sub">Public APIs only; no full-web scraping.</div></div></div><label class="live-toggle"><input id="assistant-live" type="checkbox" checked/> Search live public sources <span>PubChem · OpenAlex · Crossref · Europe PMC</span></label><div class="origin-note" style="margin-top:18px"><span>✓</span>Relevant citations retain source and license context; general answers are labeled when no source matches.</div><div style="margin-top:18px;color:#8195a8;font-size:11px;line-height:1.7">Results may include metadata and abstracts rather than full text. Open the cited source to review the original article and its license before relying on a claim.</div></div></div>`; }
function citationHtml(citations=[]){ const chemical=state.currentAssistantChemical; const save=chemical?`<button class="btn ghost assistant-save-chemical" onclick="openSaveChemical('${esc(chemical.id)}')">＋ Save identified chemical to library</button>`:''; return save+citations.slice(0,5).map(c=>`<button class="citation" data-url="${esc(c.url||'')}" data-title="${esc(c.label)}" onclick="openSourcePreview(this.dataset.url,this.dataset.title)"><b>${esc(c.label)}</b><small>${esc(c.reason||'source record')} · open internally ↗</small></button>`).join(''); }
function formatFormulaExpression(expression){ let value=expression.replace(/\\(?:text|mathrm|mathbf|mathit)\{([^{}]*)\}/g,'$1'); value=value.replace(/_\{([^{}]+)\}/g,'<sub>$1</sub>').replace(/_(\d+)/g,'<sub>$1</sub>').replace(/\^\{([^{}]+)\}/g,'<sup>$1</sup>').replace(/\^(\d+)/g,'<sup>$1</sup>'); return value.replace(/[{}]/g,'').replace(/\\,/g,' ').replace(/\\cdot/g,'·').replace(/\\/g,''); }
function assistantHtml(text=''){ const safe=esc(text); return safe.replace(/\$([^$]+)\$/g,(_,expression)=>`<span class="chem-formula">${formatFormulaExpression(expression)}</span>`).replace(/\r?\n/g,'<br>'); }
async function askAssistant(){ const input=$('#assistant-input'),q=input.value.trim(); if(!q)return; const messages=$('#chat-messages'),live=$('#assistant-live')?.checked ?? true; messages.insertAdjacentHTML('beforeend',`<div class="message user"><div class="avatar">AR</div><div><div class="bubble">${esc(q)}</div><small>You · now</small></div></div>`); input.value=''; const data=await api('/api/assistant',{method:'POST',body:JSON.stringify({question:q,live})}); const mode=data.assistant_mode==='llm_synthesis'?`${data.assistant_provider||'AI'} synthesis + live retrieval`:data.retrieved_at?'live retrieval summary':'workspace evidence'; const status=data.assistant_status||mode; const answerHtml=`<div style="color:#53b5ff;font-size:10px;text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px">Direct answer</div><div class="bubble">${assistantHtml(data.answer)}</div>`; const sourcesHtml=data.citations?.length?`<div style="color:#8195a8;font-size:10px;text-transform:uppercase;letter-spacing:.08em;margin:10px 0 6px">Research sources</div>${citationHtml(data.citations)}`:''; messages.insertAdjacentHTML('beforeend',`<div class="message"><div class="avatar">✦</div><div>${answerHtml}${sourcesHtml}<small>Assistant · ${esc(status)}</small></div></div>`); messages.scrollTop=messages.scrollHeight; }

async function ingestionView(){ shell('Data ingestion'); const cs=await api('/api/ingest/connectors'); $('#view').innerHTML=header('CONTROLLED INGESTION','Data ingestion connectors','Bring in approved open, licensed, or locally owned data without losing source and license context.','<button class="btn primary" onclick="toast(\'Upload validation flow ready\')">⇧ Validate a file</button>')+`<div class="panel" style="margin-bottom:17px"><div class="origin-note"><span>✓</span><div><b style="color:#d8e7f4">Governance policy: lawful_open_or_licensed</b><br><span>Connectors preview and normalize records; persistence should happen through an approved import job.</span></div></div></div><div class="connector-grid">${cs.map(c=>`<div class="connector-card"><span class="tag">${esc(c.source_type)}</span><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><div class="connector-footer"><span class="policy">● ${esc(c.license_policy)}</span><button class="btn ghost" onclick="previewConnector('${c.id}')">Preview</button></div></div>`).join('')}</div><div class="panel" style="margin-top:17px"><div class="panel-head"><div><div class="panel-title">Import contract</div><div class="panel-sub">Every normalized datum must carry these fields.</div></div></div><div class="result-grid"><div class="result-card"><b>Identity</b><small>Stable record ID, identifiers, and standardization status.</small></div><div class="result-card"><b>Origin</b><small>Measured, extracted, calculated, predicted, or AI-estimated.</small></div><div class="result-card"><b>Provenance</b><small>Source, publisher, URL, license, access time, and method.</small></div></div></div>`; }
async function previewConnector(id){ const data=await api('/api/ingest/preview',{method:'POST',body:JSON.stringify({connector_id:id,payload:{filename:'owned-export.csv',records:12}})}); toast(`${data.message} (${data.records_seen} records previewed)`); }
function navigate(view){ state.view=view; if(view!=='chemicals') $('#view').scrollTop=0; render(); }
document.querySelectorAll('.nav-item').forEach(btn=>btn.addEventListener('click',()=>{navigate(btn.dataset.view);$('.sidebar').classList.remove('open')}));
$('#mobile-menu').addEventListener('click',()=>$('.sidebar').classList.toggle('open'));
window.navigate=navigate; window.runSearch=runSearch; window.showChemical=showChemicalClean; window.filterTable=filterTable; window.loadAnalysis=loadAnalysis; window.selectTechnique=selectTechnique; window.askAssistant=askAssistant; window.previewConnector=previewConnector; window.toast=toast; window.openSourcePreview=openSourcePreview; window.closeSourcePreview=closeSourcePreview; window.setMoleculeStyle=setMoleculeStyle; window.resetMoleculeView=resetMoleculeView; window.toggleMoleculeSpin=toggleMoleculeSpin;
window.openSaveChemical=openSaveChemical; window.openSaveLocalChemical=openSaveLocalChemical; window.openNewLibraryFolder=openNewLibraryFolder; window.openNewLibraryItem=openNewLibraryItem; window.openNewLibraryFolderFromPicker=openNewLibraryFolderFromPicker; window.closeLibraryModal=closeLibraryModal; window.confirmFolderSave=confirmFolderSave; window.selectLibraryFolder=selectLibraryFolder; window.updatePropertyPlot=updatePropertyPlot;
initAppZoom();
render();

function graphChemicalRecord(record){ const cid=record.source?.metadata?.cid; return {...record,structure_2d_url:cid?`/api/pubchem/${cid}/structure-2d`:null,conformer_3d_url:cid?`/api/pubchem/${cid}/conformer-3d`:null}; }
function graphInspectorMarkup(c){ const image=c.structure_2d_url?`<img class="structure-image" src="${esc(c.structure_2d_url)}" alt="2D structure of ${esc(c.name)}" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><div class="structure-fallback" hidden><b>2D depiction unavailable</b><small>Try again when the public structure service is reachable.</small></div>`:`<div class="structure-fallback"><b>2D depiction unavailable</b><small>The canonical SMILES remains available below.</small></div>`; const isLive=c.type==='live_chemical'; const actions=isLive?`<button class="btn ghost" onclick="openSaveChemical('${esc(c.id)}')">＋ Save to library</button>`:`<button class="btn ghost" onclick="showChemical('${esc(c.id)}')">Open full record</button>`; return `<div class="panel-head"><div><div class="panel-title">${esc(c.name)}</div><div class="panel-sub">Chemical structure inspector · click nodes to change selection.</div></div>${actions}</div><div class="graph-identity"><span class="tag">${esc(c.formula||'formula unavailable')}</span><span class="graph-muted">${esc(c.cas_number||c.source?.title||'Public identity source')}</span></div><div class="graph-structure-2d">${image}</div><div class="structure-code"><small>Canonical SMILES</small><code>${esc(c.smiles||'Not available')}</code></div><div class="panel-head graph-3d-head"><div><div class="panel-title">Interactive 3D structure</div><div class="panel-sub">Real SDF when PubChem provides a conformer; otherwise the SMILES model is used.</div></div><div class="viewer-tools"><select class="select" aria-label="3D representation" onchange="setMoleculeStyle(this.value)"><option value="ball" selected>Ball &amp; stick</option><option value="stick">Sticks</option><option value="sphere">Space fill</option></select><button class="btn ghost" onclick="resetMoleculeView()">Reset</button><button class="btn ghost" id="molecule-spin" onclick="toggleMoleculeSpin()">Spin</button>${c.conformer_3d_url?`<a class="text-link" href="${esc(c.conformer_3d_url)}" download>Download SDF</a>`:''}</div></div><div class="viewer-3d enhanced-viewer graph-viewer" id="mol3d-graph-inspector"><div class="viewer-loading">Loading 3D conformer…</div><div class="viewer-fallback" hidden><b>3D conformer unavailable</b><small>Use the 2D depiction and canonical SMILES above.</small></div></div>`; }
function renderGraphChemicalInspector(c){ const panel=$('#graph-inspector'); if(!panel)return; state.graphChemical=c; panel.innerHTML=graphInspectorMarkup(c); setTimeout(()=>setupMolViewerClean(c.smiles,'graph-inspector',c.conformer_3d_url),0); }
async function inspectGraphChemical(id){ try{ const c=await api('/api/chemicals/'+encodeURIComponent(id)); renderGraphChemicalInspector(c); }catch(e){ toast(`Could not load chemical structure: ${e.message}`); } }
async function lookupGraphChemical(){ const input=$('#graph-chemical-query'),q=input?.value.trim(); if(!q)return; const button=$('#graph-lookup-button'); if(button)button.disabled=true; try{ const data=await api('/api/research/live?q='+encodeURIComponent(q)); const result=(data.results||[]).find(x=>x.type==='live_chemical'); if(!result){ toast('No live chemical identity match found'); return; } const c=graphChemicalRecord(result); state.liveRecords[c.id]=c; renderGraphChemicalInspector(c); }catch(e){ toast(`Chemical lookup failed: ${e.message}`); }finally{ if(button)button.disabled=false; } }
async function graphView(){ shell('Knowledge graph'); state.graph=await api('/api/graph'); const g=state.graph; const positions={}; const W=900,H=500; g.nodes.forEach(n=>{ const ring=n.type==='chemical'?170:240; const centerX=450,centerY=250; const sameType=g.nodes.filter(x=>x.type===n.type); const index=sameType.indexOf(n); positions[n.id]={x:centerX+ring*Math.cos(index/Math.max(sameType.length,1)*Math.PI*2-1.5),y:centerY+ring*.72*Math.sin(index/Math.max(sameType.length,1)*Math.PI*2-1.5)}; }); const edges=g.edges.map(e=>{const s=positions[e.source],t=positions[e.target]; return s&&t?`<line x1="${s.x}" y1="${s.y}" x2="${t.x}" y2="${t.y}" stroke="#37617c" stroke-width="1.4" stroke-dasharray="4 4"/>`:''}).join(''); const nodes=g.nodes.map(n=>{const p=positions[n.id],color=n.type==='chemical'?'#53b5ff':n.type==='experiment'?'#67e8b4':'#fbbf70'; const clickable=n.type==='chemical'?` class="graph-node chemical-node" onclick="inspectGraphChemical('${esc(n.id)}')" tabindex="0" role="button" aria-label="Inspect ${esc(n.label)}"`:''; return `<g${clickable}><circle cx="${p.x}" cy="${p.y}" r="${n.type==='chemical'?11:9}" fill="${color}" fill-opacity=".9"/><text x="${p.x}" y="${p.y+25}" text-anchor="middle" fill="#a5b8c9" font-size="10">${esc(n.label).slice(0,23)}</text></g>`}).join(''); $('#view').innerHTML=header('CONNECTED KNOWLEDGE','Knowledge graph','Click any chemical node to inspect its 2D structure and interactive 3D conformer. Search any other chemical below to preview it without adding it to the workspace.')+`<div class="graph-lookup panel"><div><div class="panel-title">Inspect any chemical</div><div class="panel-sub">Search by name, CAS number, PubChem CID, or common synonym.</div></div><div class="graph-lookup-controls"><input id="graph-chemical-query" class="select" placeholder="e.g. Paclitaxel, caffeine, 50-00-0" onkeydown="if(event.key==='Enter')lookupGraphChemical()"/><button id="graph-lookup-button" class="btn primary" onclick="lookupGraphChemical()">Find structure</button></div></div><div class="graph-workspace"><div class="panel"><div class="panel-head"><div><div class="panel-title">Workspace graph</div><div class="panel-sub">${g.nodes.length} nodes · ${g.edges.length} relationships · select a blue chemical node.</div></div><button class="btn ghost" onclick="toast('Chemical nodes are selectable; use the lookup above for any public identity.')">How it works</button></div><div class="graph-canvas"><svg viewBox="0 0 ${W} ${H}">${edges}${nodes}</svg><div class="graph-legend"><span style="--c:#53b5ff">chemical · clickable</span><span style="--c:#67e8b4">experiment</span><span style="--c:#fbbf70">reaction</span></div></div></div><div class="panel graph-inspector" id="graph-inspector"><div class="empty">Select a chemical node, or search for any chemical above, to load its structure.</div></div></div>`; }
window.inspectGraphChemical=inspectGraphChemical; window.lookupGraphChemical=lookupGraphChemical;

// Resilient viewer override: render SMILES immediately, then upgrade to a real
// 3D SDF when the public structure service responds.
function setupMolViewerClean(smiles,id,conformerUrl){ const host=document.getElementById('mol3d-'+id); if(!host)return; const fallback=host.querySelector('.viewer-fallback'),loading=host.querySelector('.viewer-loading'); const showFallback=()=>{ if(loading) loading.hidden=true; if(fallback) fallback.hidden=false; }; if(!window.$3Dmol){ showFallback(); return; } let viewer; try{ viewer=window.$3Dmol.createViewer(host,{backgroundColor:'#071421',antialias:true}); }catch(_){ showFallback(); return; } state.moleculeViewer={viewer,style:'ball',spinning:false}; const renderModel=()=>{ viewer.setStyle({},moleculeStyleObject(state.moleculeViewer.style||'ball')); viewer.zoomTo(); viewer.render(); if(loading) loading.hidden=true; }; const loadSmiles=()=>{ if(!smiles)return showFallback(); try{ viewer.addModel(smiles,'smi'); renderModel(); }catch(_){ showFallback(); } }; const loadSdf=async()=>{ if(!conformerUrl)return; const controller=new AbortController(); const timer=setTimeout(()=>controller.abort(),12000); try{ const response=await fetch(conformerUrl,{signal:controller.signal}); if(!response.ok)throw new Error('3D conformer unavailable'); const sdf=await response.text(); if(!sdf.includes('M  END'))throw new Error('Invalid SDF response'); if(typeof viewer.removeAllModels==='function')viewer.removeAllModels(); viewer.addModel(sdf,'sdf'); renderModel(); }catch(_){ /* Keep the already-rendered SMILES model visible. */ }finally{ clearTimeout(timer); } }; loadSmiles(); loadSdf(); }
function graphChemicalRecord(record){ const cid=record.source?.metadata?.cid; const params=record.smiles?`?smiles=${encodeURIComponent(record.smiles)}&name=${encodeURIComponent(record.name||'')}`:''; return {...record,structure_2d_url:cid?`/api/pubchem/${cid}/structure-2d`:null,conformer_3d_url:cid?`/api/pubchem/${cid}/conformer-3d${params}`:null}; }
